const input = $json.body ?? $json;
const executionId = typeof $execution !== 'undefined' && $execution.id ? $execution.id : Date.now();
const requestId = input.request_id || input.live_probe?.request_id || `req_${executionId}`;
const payload = input.live_probe || input;
const query = String(payload.input?.query || input.input?.query || payload.input?.skill_idea || input.input?.skill_idea || '').toLowerCase();
const skillId = payload.input?.skill_id || input.input?.skill_id || 'actor-directed-work-artifact';
const capabilities = payload.context?.expected_capabilities || input.context?.expected_capabilities || [
  'approved_skill_validation',
  'internal_skill_orchestrator_boundary',
  'actor_twin_checkpoint',
  'autonomous_work_artifact_execution',
  'trace_response'
];
const explicitCreation = /\b(create|shape|design|generate|build|define)\b[\s\S]{0,64}\b(new\s+)?(skill|agent|task-agent|task agent|subagent|sub-agent|capability)\b/i.test(query)
  || /\b(new|additional)\s+(skill|agent|task-agent|task agent|subagent|sub-agent|capability)\b/i.test(query)
  || /\b(skill|agent|task-agent|task agent|subagent|sub-agent|capability)\b[\s\S]{0,64}\b(create|shape|design|generate|build|define)\b/i.test(query);
const createSkill = explicitCreation && (input.intent === 'create_skill' || input.context?.route_decision?.decision === 'create_skill');

const response = createSkill ? {
  envelope_version: input.envelope_version || payload.envelope_version || '0.1.0',
  request_id: requestId,
  agent_id: 'agentic_butler',
  status: 'approval_required',
  approval: {
    required: true,
    gate: 'skill_spec_approval',
    summary: 'Generated skill or agent proposal is ready for human review.',
    proposed_action: 'Approve the proposal to stage SkillSpec decomposition and make the generated capability available through Agentic Butler orchestration.'
  },
  output: {
    summary: 'Agentic Butler prepared a generated capability proposal for approval.',
    skill_creation: {
      status: 'proposal_pending_approval',
      mode_of_action: 'Elicit, decompose, and stage a reusable Actor Twin controlled work behavior.',
      value_proposition: 'Transforms repeated work into a governed reusable skill.',
      usp: 'New capability becomes active only after human approval and then runs autonomously under Actor Twin routing.'
    },
    readiness: 'connected',
    side_effects: 'none',
    skill_id: skillId,
    capabilities_checked: capabilities
  },
  trace: {
    stored: true,
    trace_id: `n8n_exec_${executionId}`,
    used_agents: ['agentic_butler_shell', 'skill_orchestrator_internal_boundary', 'skill_elicitation_boundary']
  }
} : {
  envelope_version: input.envelope_version || payload.envelope_version || '0.1.0',
  request_id: requestId,
  agent_id: 'agentic_butler',
  status: 'completed',
  approval: { required: false },
  output: {
    summary: 'Agentic Butler completed autonomous Actor Twin delegated work without external side effects.',
    todos: [
      {
        what: 'Prepare requested work artifact',
        how: 'Use Actor Twin intent, approved skill boundary, and provided source context.',
        why: 'Keep the human interaction flowing while specialist agents do background work.',
        whom: 'Requesting user and relevant stakeholders',
        priority: 'high',
        comments: 'Draft/planning only; no send, schedule, publish, delete, or commit action executed.'
      }
    ],
    readiness: 'connected',
    side_effects: 'none',
    skill_id: skillId,
    capabilities_checked: capabilities,
    approval_queue: []
  },
  trace: {
    stored: true,
    trace_id: `n8n_exec_${executionId}`,
    used_agents: ['agentic_butler_shell', 'skill_orchestrator_internal_boundary']
  }
};

return [{ json: response }];
